def string_suffix(S: str) -> int:
    def similarity(A: str, B: str) -> int:
        count = 0
        for a, b in zip(A, B):
            if a == b:
                count += 1
            else:
                break
        return count

    total_similarity = 0
    for i in range(len(S)):
        suffix = S[i:]
        total_similarity += similarity(S, suffix)
    return total_similarity

# Example usage:
print(string_suffix('ababaa'))  # Output: 11
print(string_suffix('abc'))     # Output: 3
